mapper.select:
SELECT a.id, a.name, a.avatar, a.category, a.use_count AS useCount, IFNULL( (SELECT ROUND(SUM(CASE WHEN r.evaluate='like' THEN 1 ELSE 0 END)/COUNT(*),3) FROM ai_chat_record r WHERE r.agent_id = a.id AND r.evaluate IS NOT NULL AND (r.del_flag IS NULL OR r.del_flag = '0')), 0 ) AS satisfaction FROM ai_agent a WHERE a.del_flag = '0' AND a.status = 'published'
ORDER BY satisfaction DESC ORDER BY a.use_count DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM ai_chat_record
WHERE agent_id IS NOT NULL
  AND create_time >= #{startTime}
  AND create_time < #{endTime}
  AND (del_flag IS NULL OR del_flag = '0')

SELECT a.id, a.name, a.description, a.avatar, a.agent_type AS agentType, a.dify_mode AS difyMode, a.category, a.tags, a.status, a.market_config AS marketConfig, a.use_count AS useCount, a.sort, a.source, a.permission, a.create_time AS createTime, IFNULL( (SELECT ROUND(SUM(CASE WHEN r.evaluate = 'like' THEN 1 ELSE 0 END) / COUNT(*), 3) FROM ai_chat_record r WHERE r.agent_id = a.id AND r.evaluate IS NOT NULL AND (r.del_flag IS NULL OR r.del_flag = '0')), 0 ) AS satisfaction, EXISTS( SELECT 1 FROM ai_collect c WHERE c.target_id = a.id AND c.collect_type = 'agent' AND c.user_id = #{userId} ) AS favorited, (SELECT COUNT(*) FROM ai_collect c3 WHERE c3.target_id = a.id AND c3.collect_type = 'agent' ) AS collectCount, (
) AS `accessible` FROM ai_agent a WHERE a.del_flag = '0' AND a.status = 'published' AND a.name LIKE CONCAT('%', #{keyword}, '%') AND a.category = #{category}
AND JSON_CONTAINS(a.tags, JSON_QUOTE(#{tag}), '$')
AND (a.tags IS NULL OR NOT JSON_CONTAINS(a.tags, JSON_QUOTE(#{excludeTag}), '$'))
AND ()
AND NOT ()
AND a.source = #{source}
AND EXISTS(SELECT 1 FROM ai_collect c2 WHERE c2.target_id = a.id AND c2.collect_type = 'agent' AND c2.user_id = #{userId})
ORDER BY a.use_count DESC ORDER BY satisfaction DESC ORDER BY collectCount DESC ORDER BY a.create_time DESC ORDER BY a.sort DESC
